50	func newLoginCmd() *cobra.Command {
51		var insecureHTTPAuth bool
52		cmd := &cobra.Command{
53			Use:   "login",
54			Short: "Log in to Entire",
55			RunE: func(cmd *cobra.Command, _ []string) error {
56				if err := requireSecureBaseURL(insecureHTTPAuth); err != nil {
57					return err
58				}
59				return runLogin(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(), auth.NewClient(nil, insecureHTTPAuth), openBrowser)
60			},
61		}
62		addInsecureHTTPAuthFlag(cmd, &insecureHTTPAuth)
63		return cmd
64	}
65	
66	func runLogin(ctx context.Context, outW, errW io.Writer, client deviceAuthClient, openURL browserOpenFunc) error {
67		start, err := client.StartDeviceAuth(ctx)
68		if err != nil {
69			return fmt.Errorf("start login: %w", err)
70		}
71	
72		fmt.Fprintf(outW, "Device code: %s\n", start.UserCode)
73	
74		approvalURL := chooseApprovalURL(start)
75	
76		if interactive.CanPromptInteractively() {
77			// chooseApprovalURL prefers the code-embedded verification_uri_complete,
78			// so opening the URL is usually all the user needs to do. The device
79			// code is printed above regardless, so it's still available to confirm
80			// against the page (RFC 8628 §3.3.1) or to enter on the bare-URI fallback.
81			fmt.Fprintf(outW, "Press Enter to open %s in your browser to approve this login...", approvalURL)
82	
83			// Read from /dev/tty so we get a real keypress and don't consume piped stdin.
84			if err := waitForEnter(ctx); err != nil {
85				return fmt.Errorf("wait for input: %w", err)
86			}
87	
88			fmt.Fprintln(outW)
89			if err := openURL(ctx, approvalURL); err != nil {
90				fmt.Fprintf(errW, "Warning: failed to open browser: %v\n", err)
91				fmt.Fprintf(outW, "Open this URL in your browser to approve this login: %s\n", approvalURL)
92			}
93		} else {
94			fmt.Fprintf(outW, "Approval URL: %s\n", approvalURL)
95		}
96	
97		fmt.Fprintln(outW, "Waiting for approval...")
98	
99		token, refreshToken, err := waitForApproval(ctx, client, start.DeviceCode, start.ExpiresIn, time.Duration(start.Interval)*time.Second, defaultSlowDownBackoff)
100		if err != nil {
101			return fmt.Errorf("complete login: %w", err)
102		}
103	
104		if err := validateReceivedToken(token, client.BaseURL(), time.Now()); err != nil {
105			return fmt.Errorf("reject login token: %w", err)
106		}
107	
108		store := auth.NewStore()
109	
110		// Login deliberately uses the legacy SaveToken (string, string)
111		// surface — we only have an access-token string at this point;
112		// the deviceflow client doesn't return a TokenSet here.
113		if err := store.SaveToken(client.BaseURL(), token); err != nil {
114			return fmt.Errorf("save auth token: %w", err)
115		}
116	
117		// Dual-write the shared contexts.json credential model so the git
118		// remote helper (and entiredb's CLIs) can authenticate against any
119		// entitled cluster from this login. Best-effort: the legacy entry
120		// above remains the control-plane source of truth, so a failure here
121		// must not fail the login — warn and continue.
122		if _, err := auth.RecordLoginContext(token, refreshToken, true); err != nil {
123			fmt.Fprintf(errW, "Warning: logged in, but could not record a shareable context (clone via entire:// may need a re-login): %v\n", err)
124		}
125	
126		fmt.Fprintln(outW, "Login complete.")
127		return nil
128	}
129	
130	// validateReceivedToken runs minimum-trust checks on the access token
131	// the AS handed us before we persist it. The server is the authority
132	// on signature/exp; this is defense in depth aimed at catching gross
133	// misbehaviour by a compromised or misconfigured AS (e.g. handing back
134	// a token from a different issuer than the one we asked, or one whose
135	// claims are already-expired).
136	//
137	// Opaque (non-JWT) tokens are permitted — the AS may not issue JWTs at
138	// all. Only when we can parse the token as a JWT do we cross-check the
139	// claims. Unsigned (alg:none) JWTs are always rejected via
140	// tokens.ErrUnsignedJWT; every other parse failure (3-segment-but-not-
141	// base64, payload-not-JSON, header-not-JSON, etc.) is treated as opaque
142	// and accepted, so a server issuing dot-bearing non-JWT bearer tokens
143	// can still log in.
144	func validateReceivedToken(rawToken, issuerURL string, now time.Time) error {
145		claims, err := tokens.ParseClaims(rawToken)
146		if errors.Is(err, tokens.ErrUnsignedJWT) {
147			return err //nolint:wrapcheck // sentinel surfaces verbatim for caller's errors.Is
148		}
149		if err != nil {
150			return nil //nolint:nilerr // any parse failure other than alg:none means the token isn't a JWT — opaque tokens are valid
151		}
152	
153		// iss check: the token must claim to come from the issuer we sent
154		// the device-code request to. A mismatch means either the AS is
155		// misconfigured or someone's playing games.
156		if issErr := issMatches(claims.Issuer, issuerURL); issErr != nil {
157			return issErr
158		}
159	
160		// exp sanity: a token that's already expired before we even store
161		// it is a smell. Don't reject if exp is unset (some servers omit).
162		if !claims.ExpiresAt.IsZero() && !now.Before(claims.ExpiresAt) {
163			return fmt.Errorf("token already expired (exp=%s, now=%s)",
164				claims.ExpiresAt.Format(time.RFC3339), now.Format(time.RFC3339))
165		}
166	
167		return nil
168	}
169	
170	// issMatches reports whether claimed equals expected after stripping path/
171	// query/fragment via api.OriginOnly, so "https://issuer/" and "https://issuer"
172	// match. Returns nil on match or when the iss claim is empty (some servers
173	// omit it — the server still does the real check on every request).
174	func issMatches(claimed, expected string) error {
175		if claimed == "" {
176			return nil
177		}
178		normClaimed := api.OriginOnly(claimed)
179		normExpected := api.OriginOnly(expected)
180		if normClaimed != normExpected {
181			return fmt.Errorf("iss mismatch: token claims %q, expected %q", normClaimed, normExpected)
182		}
183		return nil
184	}
185	
186	func waitForApproval(ctx context.Context, poller deviceAuthClient, deviceCode string, expiresIn int, interval, slowDownBackoff time.Duration) (accessToken, refreshToken string, err error) {
187		expiry := time.Duration(expiresIn) * time.Second
188		if expiry <= 0 || expiry > maxExpiresIn {
189			expiry = maxExpiresIn
190		}
191		deadline := time.Now().Add(expiry)
192		pollInterval := interval
193		if pollInterval <= 0 {
194			pollInterval = fallbackDeviceAuthPollInterval
195		}
196	
197		consecutiveErrors := 0
198	
199		for {
200			if time.Now().After(deadline) {
201				return "", "", errors.New("device authorization expired")
202			}
203	
204			result, err := poller.PollDeviceAuth(ctx, deviceCode)
205			if err != nil {
206				consecutiveErrors++
207				if consecutiveErrors >= maxTransientErrors {
208					return "", "", fmt.Errorf("poll approval status (after %d consecutive failures): %w", consecutiveErrors, err)
209				}
210				// Transient error — wait and retry.
211				select {
212				case <-ctx.Done():
213					return "", "", fmt.Errorf("wait for approval: %w", ctx.Err())
214				case <-time.After(pollInterval):
215				}
216				continue
217			}
218			consecutiveErrors = 0
219	
220			switch result.Error {
221			case "":
222				if result.AccessToken == "" {
223					return "", "", errors.New("device authorization completed without a token")
224				}
225				return result.AccessToken, result.RefreshToken, nil
226			case "authorization_pending":
227				// no-op, will sleep and retry below
228			case "slow_down":
229				pollInterval += slowDownBackoff
230				if pollInterval > maxPollInterval {
231					pollInterval = maxPollInterval
232				}
233			case "access_denied":
234				return "", "", errors.New("device authorization denied")
235			case "expired_token":
236				return "", "", errors.New("device authorization expired")
237			default:
238				if result.ErrorDescription != "" {
239					return "", "", fmt.Errorf("device authorization failed: %s: %s", result.Error, result.ErrorDescription)
240				}
241				return "", "", fmt.Errorf("device authorization failed: %s", result.Error)
242			}
243	
244			select {
245			case <-ctx.Done():
246				return "", "", fmt.Errorf("wait for approval: %w", ctx.Err())
247			case <-time.After(pollInterval):
248			}
249		}
250	}
251	
252	// waitForEnter reads a line from /dev/tty, blocking until the user presses Enter.
253	// If /dev/tty cannot be opened (e.g. on Windows), it returns immediately.
254	// Returns ctx.Err() if the context is cancelled before the user presses Enter.
255	func waitForEnter(ctx context.Context) error {
256		tty, err := os.Open("/dev/tty")
257		if err != nil {
258			return nil //nolint:nilerr // tty unavailable (e.g. Windows) — skip prompt silently
259		}
260	
261		done := make(chan error, 1)
262		go func() {
263			reader := bufio.NewReader(tty)
264			_, err := reader.ReadString('\n')
265			done <- err
266		}()
267	
268		select {
269		case <-ctx.Done():
270			// Close tty to unblock the reading goroutine.
271			_ = tty.Close()
272			return fmt.Errorf("interrupted: %w", ctx.Err())
273		case <-done:
274			_ = tty.Close()
275			return nil
276		}
277	}
278	
279	func openBrowser(ctx context.Context, browserURL string) error {
280		u, err := url.Parse(browserURL)
281		if err != nil || (u.Scheme != "https" && u.Scheme != "http") {
282			return fmt.Errorf("refusing to open non-HTTP URL: %s", browserURL)
283		}
284	
285		var command string
286		var args []string
287	
288		switch runtime.GOOS {
289		case "darwin":
290			command = "open"
291			args = []string{browserURL}
292		case "linux":
293			command = "xdg-open"
294			args = []string{browserURL}
295		case "windows":
296			command = "cmd"
297			args = []string{"/c", "start", "", browserURL}
298		default:
299			return fmt.Errorf("unsupported platform %s", runtime.GOOS)
300		}
301	
302		cmd := exec.CommandContext(ctx, command, args...)
303		if err := cmd.Start(); err != nil {
304			return fmt.Errorf("start browser command %q: %w", command, err)
305		}
306	
307		if err := cmd.Process.Release(); err != nil {
308			return fmt.Errorf("release browser process: %w", err)
309		}
310	
311		return nil
312	}
