package cli

import (
	"bufio"
	"context"
	"errors"
	"fmt"
	"io"
	"net/url"
	"os"
	"os/exec"
	"runtime"
	"time"

	"github.com/entireio/auth-go/tokens"
	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/entireio/cli/cmd/entire/cli/auth"
	"github.com/entireio/cli/cmd/entire/cli/interactive"
	"github.com/spf13/cobra"
)

const fallbackDeviceAuthPollInterval = time.Second
const defaultSlowDownBackoff = 5 * time.Second
const maxPollInterval = 30 * time.Second
const maxExpiresIn = 15 * time.Minute
const maxTransientErrors = 5

// browserOpenFunc is the signature for opening a URL in the user's browser.
type browserOpenFunc func(ctx context.Context, url string) error

// chooseApprovalURL prefers verification_uri_complete (RFC 8628 §3.3.1) so the
// browser lands on a URL with the user_code already in the query string —
// most verification pages prefill the input from that param, sparing the
// user from typing. Falls back to the bare verification_uri when the AS
// didn't supply a complete form.
func chooseApprovalURL(start *auth.DeviceAuthStart) string {
	if start.VerificationURIComplete != "" {
		return start.VerificationURIComplete
	}
	return start.VerificationURI
}

// deviceAuthClient abstracts the auth client so runLogin and waitForApproval can be unit-tested.
type deviceAuthClient interface {
	StartDeviceAuth(ctx context.Context) (*auth.DeviceAuthStart, error)
	PollDeviceAuth(ctx context.Context, deviceCode string) (*auth.DeviceAuthPoll, error)
	BaseURL() string
}

func newLoginCmd() *cobra.Command {
	var insecureHTTPAuth bool
	cmd := &cobra.Command{
		Use:   "login",
		Short: "Log in to Entire",
		RunE: func(cmd *cobra.Command, _ []string) error {
			if err := requireSecureBaseURL(insecureHTTPAuth); err != nil {
				return err
			}
			return runLogin(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(), auth.NewClient(nil, insecureHTTPAuth), openBrowser)
		},
	}
	addInsecureHTTPAuthFlag(cmd, &insecureHTTPAuth)
	return cmd
}

func runLogin(ctx context.Context, outW, errW io.Writer, client deviceAuthClient, openURL browserOpenFunc) error {
	start, err := client.StartDeviceAuth(ctx)
	if err != nil {
		return fmt.Errorf("start login: %w", err)
	}

	fmt.Fprintf(outW, "Device code: %s\n", start.UserCode)

	approvalURL := chooseApprovalURL(start)

	if interactive.CanPromptInteractively() {
		// chooseApprovalURL prefers the code-embedded verification_uri_complete,
		// so opening the URL is usually all the user needs to do. The device
		// code is printed above regardless, so it's still available to confirm
		// against the page (RFC 8628 §3.3.1) or to enter on the bare-URI fallback.
		fmt.Fprintf(outW, "Press Enter to open %s in your browser to approve this login...", approvalURL)

		// Read from /dev/tty so we get a real keypress and don't consume piped stdin.
		if err := waitForEnter(ctx); err != nil {
			return fmt.Errorf("wait for input: %w", err)
		}

		fmt.Fprintln(outW)
		if err := openURL(ctx, approvalURL); err != nil {
			fmt.Fprintf(errW, "Warning: failed to open browser: %v\n", err)
			fmt.Fprintf(outW, "Open this URL in your browser to approve this login: %s\n", approvalURL)
		}
	} else {
		fmt.Fprintf(outW, "Approval URL: %s\n", approvalURL)
	}

	fmt.Fprintln(outW, "Waiting for approval...")

	token, refreshToken, err := waitForApproval(ctx, client, start.DeviceCode, start.ExpiresIn, time.Duration(start.Interval)*time.Second, defaultSlowDownBackoff)
	if err != nil {
		return fmt.Errorf("complete login: %w", err)
	}

	if err := validateReceivedToken(token, client.BaseURL(), time.Now()); err != nil {
		return fmt.Errorf("reject login token: %w", err)
	}

	store := auth.NewStore()

	// Login deliberately uses the legacy SaveToken (string, string)
	// surface — we only have an access-token string at this point;
	// the deviceflow client doesn't return a TokenSet here.
	if err := store.SaveToken(client.BaseURL(), token); err != nil {
		return fmt.Errorf("save auth token: %w", err)
	}

	// Dual-write the shared contexts.json credential model so the git
	// remote helper (and entiredb's CLIs) can authenticate against any
	// entitled cluster from this login. Best-effort: the legacy entry
	// above remains the control-plane source of truth, so a failure here
	// must not fail the login — warn and continue.
	if _, err := auth.RecordLoginContext(token, refreshToken, true); err != nil {
		fmt.Fprintf(errW, "Warning: logged in, but could not record a shareable context (clone via entire:// may need a re-login): %v\n", err)
	}

	fmt.Fprintln(outW, "Login complete.")
	return nil
}

// validateReceivedToken runs minimum-trust checks on the access token
// the AS handed us before we persist it. The server is the authority
// on signature/exp; this is defense in depth aimed at catching gross
// misbehaviour by a compromised or misconfigured AS (e.g. handing back
// a token from a different issuer than the one we asked, or one whose
// claims are already-expired).
//
// Opaque (non-JWT) tokens are permitted — the AS may not issue JWTs at
// all. Only when we can parse the token as a JWT do we cross-check the
// claims. Unsigned (alg:none) JWTs are always rejected via
// tokens.ErrUnsignedJWT; every other parse failure (3-segment-but-not-
// base64, payload-not-JSON, header-not-JSON, etc.) is treated as opaque
// and accepted, so a server issuing dot-bearing non-JWT bearer tokens
// can still log in.
func validateReceivedToken(rawToken, issuerURL string, now time.Time) error {
	claims, err := tokens.ParseClaims(rawToken)
	if errors.Is(err, tokens.ErrUnsignedJWT) {
		return err //nolint:wrapcheck // sentinel surfaces verbatim for caller's errors.Is
	}
	if err != nil {
		return nil //nolint:nilerr // any parse failure other than alg:none means the token isn't a JWT — opaque tokens are valid
	}

	// iss check: the token must claim to come from the issuer we sent
	// the device-code request to. A mismatch means either the AS is
	// misconfigured or someone's playing games.
	if issErr := issMatches(claims.Issuer, issuerURL); issErr != nil {
		return issErr
	}

	// exp sanity: a token that's already expired before we even store
	// it is a smell. Don't reject if exp is unset (some servers omit).
	if !claims.ExpiresAt.IsZero() && !now.Before(claims.ExpiresAt) {
		return fmt.Errorf("token already expired (exp=%s, now=%s)",
			claims.ExpiresAt.Format(time.RFC3339), now.Format(time.RFC3339))
	}

	return nil
}

// issMatches reports whether claimed equals expected after stripping path/
// query/fragment via api.OriginOnly, so "https://issuer/" and "https://issuer"
// match. Returns nil on match or when the iss claim is empty (some servers
// omit it — the server still does the real check on every request).
func issMatches(claimed, expected string) error {
	if claimed == "" {
		return nil
	}
	normClaimed := api.OriginOnly(claimed)
	normExpected := api.OriginOnly(expected)
	if normClaimed != normExpected {
		return fmt.Errorf("iss mismatch: token claims %q, expected %q", normClaimed, normExpected)
	}
	return nil
}

func waitForApproval(ctx context.Context, poller deviceAuthClient, deviceCode string, expiresIn int, interval, slowDownBackoff time.Duration) (accessToken, refreshToken string, err error) {
	expiry := time.Duration(expiresIn) * time.Second
	if expiry <= 0 || expiry > maxExpiresIn {
		expiry = maxExpiresIn
	}
	deadline := time.Now().Add(expiry)
	pollInterval := interval
	if pollInterval <= 0 {
		pollInterval = fallbackDeviceAuthPollInterval
	}

	consecutiveErrors := 0

	for {
		if time.Now().After(deadline) {
			return "", "", errors.New("device authorization expired")
		}

		result, err := poller.PollDeviceAuth(ctx, deviceCode)
		if err != nil {
			consecutiveErrors++
			if consecutiveErrors >= maxTransientErrors {
				return "", "", fmt.Errorf("poll approval status (after %d consecutive failures): %w", consecutiveErrors, err)
			}
			// Transient error — wait and retry.
			select {
			case <-ctx.Done():
				return "", "", fmt.Errorf("wait for approval: %w", ctx.Err())
			case <-time.After(pollInterval):
			}
			continue
		}
		consecutiveErrors = 0

		switch result.Error {
		case "":
			if result.AccessToken == "" {
				return "", "", errors.New("device authorization completed without a token")
			}
			return result.AccessToken, result.RefreshToken, nil
		case "authorization_pending":
			// no-op, will sleep and retry below
		case "slow_down":
			pollInterval += slowDownBackoff
			if pollInterval > maxPollInterval {
				pollInterval = maxPollInterval
			}
		case "access_denied":
			return "", "", errors.New("device authorization denied")
		case "expired_token":
			return "", "", errors.New("device authorization expired")
		default:
			if result.ErrorDescription != "" {
				return "", "", fmt.Errorf("device authorization failed: %s: %s", result.Error, result.ErrorDescription)
			}
			return "", "", fmt.Errorf("device authorization failed: %s", result.Error)
		}

		select {
		case <-ctx.Done():
			return "", "", fmt.Errorf("wait for approval: %w", ctx.Err())
		case <-time.After(pollInterval):
		}
	}
}

// waitForEnter reads a line from /dev/tty, blocking until the user presses Enter.
// If /dev/tty cannot be opened (e.g. on Windows), it returns immediately.
// Returns ctx.Err() if the context is cancelled before the user presses Enter.
func waitForEnter(ctx context.Context) error {
	tty, err := os.Open("/dev/tty")
	if err != nil {
		return nil //nolint:nilerr // tty unavailable (e.g. Windows) — skip prompt silently
	}

	done := make(chan error, 1)
	go func() {
		reader := bufio.NewReader(tty)
		_, err := reader.ReadString('\n')
		done <- err
	}()

	select {
	case <-ctx.Done():
		// Close tty to unblock the reading goroutine.
		_ = tty.Close()
		return fmt.Errorf("interrupted: %w", ctx.Err())
	case <-done:
		_ = tty.Close()
		return nil
	}
}

func openBrowser(ctx context.Context, browserURL string) error {
	u, err := url.Parse(browserURL)
	if err != nil || (u.Scheme != "https" && u.Scheme != "http") {
		return fmt.Errorf("refusing to open non-HTTP URL: %s", browserURL)
	}

	var command string
	var args []string

	switch runtime.GOOS {
	case "darwin":
		command = "open"
		args = []string{browserURL}
	case "linux":
		command = "xdg-open"
		args = []string{browserURL}
	case "windows":
		command = "cmd"
		args = []string{"/c", "start", "", browserURL}
	default:
		return fmt.Errorf("unsupported platform %s", runtime.GOOS)
	}

	cmd := exec.CommandContext(ctx, command, args...)
	if err := cmd.Start(); err != nil {
		return fmt.Errorf("start browser command %q: %w", command, err)
	}

	if err := cmd.Process.Release(); err != nil {
		return fmt.Errorf("release browser process: %w", err)
	}

	return nil
}

package auth

import (
	"context"
	"errors"
	"net/http"
	"strings"
	"time"

	"github.com/entireio/auth-go/deviceflow"
	"github.com/entireio/auth-go/tokens"
	"github.com/entireio/cli/cmd/entire/cli/api"
)

// nowFunc is the package's clock. Override in tests.
var nowFunc = time.Now

// DeviceAuthStart preserves the historical type name; the shape now
// matches deviceflow.DeviceCode field-for-field.
type DeviceAuthStart = deviceflow.DeviceCode

// DeviceAuthPoll is the historical token-poll response shape. The shim
// flattens deviceflow's typed errors back into the Error field so
// existing login.go logic that switches on result.Error keeps working.
//
// ErrorDescription carries the optional `error_description` from the
// server's RFC 8628 §3.5 error response, when present. Used to give
// callers a more actionable message than the bare error code.
type DeviceAuthPoll struct {
	AccessToken      string
	RefreshToken     string
	TokenType        string
	ExpiresIn        int
	Scope            string
	Error            string
	ErrorDescription string
}

// Client wraps a deviceflow.Client preconfigured for whichever provider
// version is active. See CurrentProvider for the resolution rules
// (ENTIRE_AUTH_PROVIDER_VERSION wins, then split-host auto-detect,
// then v1 fallback).
type Client struct {
	inner *deviceflow.Client
}

// NewClient constructs a Client targeting the active provider version.
// httpClient.Transport is reused when non-nil (its TLS / proxy config
// flows through); a nil httpClient or nil Transport falls back to the
// deviceflow default (http.DefaultTransport).
//
// HTTPS is required by default. Loopback http:// (localhost, 127.0.0.1,
// ::1) is always permitted — see isLoopbackHTTP. allowInsecureHTTP=true
// additionally permits non-loopback http:// for cases like local-dev
// auth hosts on a private network (e.g. http://devbox.internal); the
// CLI plumbs this from the --insecure-http-auth flag.
func NewClient(httpClient *http.Client, allowInsecureHTTP bool) *Client {
	p := CurrentProvider()
	issuer := api.AuthBaseURL()
	var transport http.RoundTripper
	if httpClient != nil {
		transport = httpClient.Transport
	}
	return &Client{inner: &deviceflow.Client{
		Transport: transport,
		BaseURL:   issuer,
		ClientID:  p.ClientID,
		// offline_access asks the authorization server for a refresh token.
		// The server only mints one when it's requested (it's client-gated),
		// so without this the device login is access-token-only and silent
		// refresh is impossible.
		Scope:             "cli offline_access",
		UserAgent:         p.ClientID,
		DeviceCodePath:    p.DeviceCodePath,
		TokenPath:         p.TokenPath,
		AllowInsecureHTTP: allowInsecureHTTP || isLoopbackHTTP(issuer),
	}}
}

// BaseURL returns the issuer base URL this client talks to.
func (c *Client) BaseURL() string { return c.inner.BaseURL }

// StartDeviceAuth requests a fresh device code.
func (c *Client) StartDeviceAuth(ctx context.Context) (*DeviceAuthStart, error) {
	return c.inner.StartDeviceAuth(ctx) //nolint:wrapcheck // shim preserves the lib's wrapped errors verbatim
}

// PollDeviceAuth polls the token endpoint. On any OAuth-protocol error
// (recognised RFC 8628 §3.5 sentinel or unknown but spec-shaped code
// like invalid_request / invalid_client / server_error), the wire-side
// code is returned in DeviceAuthPoll.Error so the existing polling
// loop in login.go can branch on it — known codes hit the dedicated
// switch arms, unknown codes fall through to the default arm and fail
// fast. Non-protocol errors (network, decode) are returned as a real
// error and treated as transient by the polling loop.
func (c *Client) PollDeviceAuth(ctx context.Context, deviceCode string) (*DeviceAuthPoll, error) {
	t, err := c.inner.PollDeviceAuth(ctx, deviceCode)
	if err != nil {
		if code, description, ok := oauthErrorParts(err); ok {
			return &DeviceAuthPoll{
				Error:            code,
				ErrorDescription: description,
			}, nil
		}
		return nil, err //nolint:wrapcheck // shim returns deviceflow errors verbatim so callers can errors.Is on sentinels
	}

	return &DeviceAuthPoll{
		AccessToken:  t.AccessToken,
		RefreshToken: t.RefreshToken,
		TokenType:    t.TokenType,
		ExpiresIn:    secondsUntil(t),
		Scope:        t.Scope,
	}, nil
}

// oauthErrorParts inspects err for either a recognised RFC 8628 §3.5
// sentinel or the generic "oauth error: <code>" wrapper deviceflow uses
// for unrecognised but spec-shaped codes (RFC 6749 §5.2: invalid_request,
// invalid_client, server_error, …).
//
// On a match, returns the wire-side code, any error_description the
// server included, and ok=true. Otherwise returns "", "", false — the
// caller should treat the error as a transport/decode failure.
//
// Surfacing unknown codes as ok=true is what keeps login.go's polling
// loop fast-failing on terminal OAuth rejections instead of treating
// them as transient and retrying ~5 times.
func oauthErrorParts(err error) (code, description string, ok bool) {
	switch {
	case errors.Is(err, deviceflow.ErrAuthorizationPending):
		code = "authorization_pending"
	case errors.Is(err, deviceflow.ErrSlowDown):
		code = "slow_down"
	case errors.Is(err, deviceflow.ErrAccessDenied):
		code = "access_denied"
	case errors.Is(err, deviceflow.ErrExpiredToken):
		code = "expired_token"
	case errors.Is(err, deviceflow.ErrInvalidGrant):
		code = "invalid_grant"
	default:
		// Unknown but legitimate OAuth codes come back from
		// deviceflow.errCodeToSentinel as fmt.Errorf("oauth error: %s",
		// code), optionally wrapped a second time with ": <description>"
		// when the server supplied error_description.
		const oauthPrefix = "oauth error: "
		rest, hadPrefix := strings.CutPrefix(err.Error(), oauthPrefix)
		if !hadPrefix {
			return "", "", false
		}
		if c, d, hasDesc := strings.Cut(rest, ": "); hasDesc {
			return c, d, true
		}
		return rest, "", true
	}
	description = descriptionFromSentinelError(err, code)
	return code, description, true
}

// descriptionFromSentinelError pulls the description suffix out of a
// wrapped sentinel error. The deviceflow lib uses
// fmt.Errorf("%w: %s", sentinel, description) when the server included
// an error_description, so the formatted error reads
// "<code>: <description>". Stripping the "<code>: " prefix yields the
// description; absent prefix means the server didn't supply one.
func descriptionFromSentinelError(err error, code string) string {
	msg := err.Error()
	prefix := code + ": "
	if rest, ok := strings.CutPrefix(msg, prefix); ok {
		return rest
	}
	return ""
}

// secondsUntil computes seconds-until-expiry for a TokenSet with an
// absolute ExpiresAt. Returns 0 when no expiry is set or when ExpiresAt
// is already in the past (clock skew, scheduling delays) — historically
// ExpiresIn was non-negative and downstream loggers / display code don't
// expect to see a negative value.
func secondsUntil(t *tokens.TokenSet) int {
	if t.ExpiresAt.IsZero() {
		return 0
	}
	return max(0, int(t.ExpiresAt.Unix()-nowFunc().Unix()))
}

package auth

import (
	"os"
	"strings"
	"sync"

	"github.com/entireio/cli/cmd/entire/cli/api"
)

// ProviderVersionEnvVar overrides the auto-detected provider version.
// Set to "v1" or "v2"; see effectiveProviderVersion for resolution.
// Read once at process startup via CurrentProvider.
const ProviderVersionEnvVar = "ENTIRE_AUTH_PROVIDER_VERSION"

// Provider captures the per-surface bits of OAuth wiring.
//
// STSPath is the RFC 8693 token-exchange endpoint. v1 is the legacy
// single-host surface where the auth and data API live at the same
// origin; the same-host shortcut in tokenmanager.Token always wins and
// STS is never invoked, so v1.STSPath is left empty. v2 exposes a
// dedicated STS path because it's used in split-host deployments
// (e.g. us.auth.partial.to mints, partial.to consumes).
//
// AuthTokensPath is the base path for the auth-tokens management
// endpoint family (list / revoke). Routed at the api.Client layer via
// (*api.Client).WithAuthTokensPath so the provider table is the single
// source of truth — no env-var duplication between auth/ and api/.
type Provider struct {
	ClientID       string
	DeviceCodePath string
	TokenPath      string
	STSPath        string
	AuthTokensPath string
}

var providers = map[string]Provider{
	"v1": { //nolint:gosec // OAuth client_id and endpoint paths, not credentials
		ClientID:       "entire-cli",
		DeviceCodePath: "/oauth/device/code",
		TokenPath:      "/oauth/token",
		AuthTokensPath: "/api/v1/auth/tokens",
	},
	"v2": { //nolint:gosec // OAuth client_id and endpoint paths, not credentials
		// Matches an OIDC-standard auth server's discovery doc — confirmed
		// against us.auth.partial.to's /.well-known/openid-configuration.
		// Device authorization, token poll, and RFC 8693 exchange all hit
		// the standard endpoints; grant_type differentiates token vs
		// exchange at the shared /oauth/token endpoint.
		ClientID:       "entire-cli",
		DeviceCodePath: "/device_authorization",
		TokenPath:      "/oauth/token",
		STSPath:        "/oauth/token",
		// API token management lives on the data API (not the auth host).
		// auth.go / logout.go pass api.AuthBaseURL() for the keyring key,
		// but the AuthTokensPath calls should route to api.BaseURL() in
		// split-host setups — see TODO in auth.go's newAuthHostAPIClient.
		AuthTokensPath: "/api/v1/auth/tokens",
	},
}

// resolveProvider returns the Provider matching version. Defaulting
// (rather than erroring) on unrecognised values keeps old binaries safe
// if a future v3 ever lands. Pure function — no env reads — so unit
// tests can exercise the routing table without env-var gymnastics.
func resolveProvider(version string) Provider {
	switch strings.TrimSpace(version) {
	case "v2":
		return providers["v2"]
	default:
		return providers["v1"]
	}
}

// effectiveProviderVersion resolves the version string fed into
// resolveProvider. Order: explicit env var > split-host auto-detect > v1.
//
// The CLI is split-host by default (us.auth.entire.io for auth, entire.io
// for data), so unset env vars take the auto-detect branch and resolve to
// v2 — the OIDC surface us.auth.entire.io serves. v1 only kicks in when a
// caller explicitly collapses both origins onto a single non-OIDC host.
func effectiveProviderVersion() string {
	if v := strings.TrimSpace(os.Getenv(ProviderVersionEnvVar)); v != "" {
		return v
	}
	if api.IsSplitHost() {
		return "v2"
	}
	return "v1"
}

var (
	providerOnce     sync.Once
	resolvedProvider Provider

	// providerForTest, when non-nil, short-circuits CurrentProvider so
	// tests can install a specific Provider without racing the
	// process-wide sync.Once (which freezes the first observation
	// forever). Mutated only via SetProviderForTest. Production code
	// never reads this var.
	providerForTest *Provider
	providerTestMu  sync.Mutex
)

// CurrentProvider returns the active Provider for this process.
// Resolution freezes on the first call (env vars must be set before
// then). Tests bypass the singleton via SetProviderForTest.
func CurrentProvider() Provider {
	providerTestMu.Lock()
	override := providerForTest
	providerTestMu.Unlock()
	if override != nil {
		return *override
	}
	providerOnce.Do(func() {
		resolvedProvider = resolveProvider(effectiveProviderVersion())
	})
	return resolvedProvider
}

// SetProviderForTest installs p as the Provider returned by
// CurrentProvider for the duration of the test, and registers a
// t.Cleanup to remove the override. Test-only.
//
// Takes a tiny interface rather than *testing.T so production builds
// don't import testing.
func SetProviderForTest(t interface {
	Helper()
	Cleanup(f func())
}, p Provider) {
	t.Helper()
	providerTestMu.Lock()
	prev := providerForTest
	providerForTest = &p
	providerTestMu.Unlock()
	t.Cleanup(func() {
		providerTestMu.Lock()
		providerForTest = prev
		providerTestMu.Unlock()
	})
}

