21	// returned OAuthErrorResponse is unsanitised; callers must pass it through
22	// SanitizeDescription before formatting it for logs or terminals. If the body
23	// is not an OAuth JSON error, the returned error contains a bounded, sanitised
24	// fallback message suitable for logs and terminals.
25	//
26	// Return-shape contract: a non-nil *OAuthErrorResponse is returned only
27	// when its Error field is non-empty. Callers are safe to dereference
28	// apiErr.Error immediately after a nil-error check, but a future change
29	// that returns a partial apiErr would break that — keep the invariant
30	// when editing this function.
31	func ReadOAuthError(resp *http.Response) (*OAuthErrorResponse, error) {
32		body, err := readLimitedBody(resp.Body)
33		if err != nil {
34			return nil, fmt.Errorf("status %d: %w", resp.StatusCode, err)
35		}
36	
37		var apiErr OAuthErrorResponse
38		if err := json.Unmarshal(bytes.TrimSpace(body), &apiErr); err == nil {
39			if strings.TrimSpace(apiErr.Error) != "" {
40				return &apiErr, nil
41			}
42			if desc := SanitizeDescription(apiErr.ErrorDescription); desc != "" {
43				return nil, fmt.Errorf("status %d: %s", resp.StatusCode, desc)
44			}
45		}
46	
47		text := SanitizeDescription(string(body))
48		if text != "" {
49			return nil, fmt.Errorf("status %d: %s", resp.StatusCode, text)
50		}
51		return nil, fmt.Errorf("status %d", resp.StatusCode)
52	}
53	
54	func readLimitedBody(r io.Reader) ([]byte, error) {
55		body, err := io.ReadAll(io.LimitReader(r, MaxResponseBytes+1))
56		if err != nil {
57			return nil, err
58		}
59		if len(body) > MaxResponseBytes {
60			return nil, ErrResponseTooLarge
61		}
62		return body, nil
63	}
