package oauthhttp

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strings"
)

// OAuthErrorResponse is the standard OAuth error response shape used by
// RFC 6749-family endpoints.
type OAuthErrorResponse struct {
	Error            string `json:"error"`
	ErrorDescription string `json:"error_description"`
}

// ReadOAuthError reads a non-success OAuth response body and returns the
// parsed OAuth error object when the server sent one. ErrorDescription on a
// returned OAuthErrorResponse is unsanitised; callers must pass it through
// SanitizeDescription before formatting it for logs or terminals. If the body
// is not an OAuth JSON error, the returned error contains a bounded, sanitised
// fallback message suitable for logs and terminals.
//
// Return-shape contract: a non-nil *OAuthErrorResponse is returned only
// when its Error field is non-empty. Callers are safe to dereference
// apiErr.Error immediately after a nil-error check, but a future change
// that returns a partial apiErr would break that — keep the invariant
// when editing this function.
func ReadOAuthError(resp *http.Response) (*OAuthErrorResponse, error) {
	body, err := readLimitedBody(resp.Body)
	if err != nil {
		return nil, fmt.Errorf("status %d: %w", resp.StatusCode, err)
	}

	var apiErr OAuthErrorResponse
	if err := json.Unmarshal(bytes.TrimSpace(body), &apiErr); err == nil {
		if strings.TrimSpace(apiErr.Error) != "" {
			return &apiErr, nil
		}
		if desc := SanitizeDescription(apiErr.ErrorDescription); desc != "" {
			return nil, fmt.Errorf("status %d: %s", resp.StatusCode, desc)
		}
	}

	text := SanitizeDescription(string(body))
	if text != "" {
		return nil, fmt.Errorf("status %d: %s", resp.StatusCode, text)
	}
	return nil, fmt.Errorf("status %d", resp.StatusCode)
}

func readLimitedBody(r io.Reader) ([]byte, error) {
	body, err := io.ReadAll(io.LimitReader(r, MaxResponseBytes+1))
	if err != nil {
		return nil, err
	}
	if len(body) > MaxResponseBytes {
		return nil, ErrResponseTooLarge
	}
	return body, nil
}

package oauthhttp

import "time"

// MaxExpiresInSeconds caps a server-provided OAuth expires_in (seconds)
// before it is multiplied into a time.Duration. Without a ceiling, a value
// above ~9.2e9 overflows time.Duration's int64 nanosecond range, wrapping
// the derived expiry into the past so a freshly-issued token looks
// already-expired. 100 years is far beyond any real token lifetime and
// safely below the overflow threshold.
const MaxExpiresInSeconds = 100 * 365 * 24 * 60 * 60

// ExpiresInDuration converts a server-provided expires_in (seconds) into a
// time.Duration, clamping at MaxExpiresInSeconds to avoid int64 overflow.
// Callers still gate on expires_in > 0 where a non-positive value is
// invalid; this helper only defends the upper bound.
func ExpiresInDuration(secs int) time.Duration {
	if secs > MaxExpiresInSeconds {
		secs = MaxExpiresInSeconds
	}
	return time.Duration(secs) * time.Second
}

package oauthhttp

import "net/http"

// HTTPClient builds the *http.Client used for one OAuth request.
//
// Always returns a freshly-allocated *http.Client so this library's
// requests are isolated from mutations to http.DefaultClient (any
// process-wide Timeout or Transport swap by another package would
// otherwise be inherited). The underlying Transport is the
// caller-supplied transport when non-nil, or http.DefaultTransport
// otherwise — sharing a Transport is intentional (it owns the
// connection pool) and safe (Transport.RoundTrip is concurrent-safe).
//
// Per-request timeouts must be driven by ctx.WithTimeout in the
// caller, not by *http.Client.Timeout — the body-read happens after
// client.Do returns, and Client.Timeout would cancel that read.
func HTTPClient(transport http.RoundTripper) *http.Client {
	if transport == nil {
		transport = http.DefaultTransport
	}
	return &http.Client{Transport: transport}
}

