176		if err := req.validate(); err != nil {
177			return nil, fmt.Errorf("refresh token: %w", err)
178		}
179	
180		form := buildForm(req)
181	
182		endpoint, err := resolveURL(c.BaseURL, c.Path, c.AllowInsecureHTTP)
183		if err != nil {
184			return nil, fmt.Errorf("refresh token: resolve URL: %w", err)
185		}
186	
187		if timeout := c.requestTimeout(); timeout > 0 {
188			var cancel context.CancelFunc
189			ctx, cancel = context.WithTimeout(ctx, timeout)
190			defer cancel()
191		}
192	
193		httpReq, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint, strings.NewReader(form.Encode()))
194		if err != nil {
195			return nil, fmt.Errorf("refresh token: create request: %w", err)
196		}
197		httpReq.Header.Set("Accept", "application/json")
198		httpReq.Header.Set("Content-Type", "application/x-www-form-urlencoded")
199		if c.UserAgent != "" {
200			httpReq.Header.Set("User-Agent", c.UserAgent)
201		}
202		if req.ClientID != "" {
203			// QueryEscape per RFC 6749 §2.3.1 — client credentials are
204			// form-urlencoded before being placed in the Basic header; spec-
205			// compliant servers QueryUnescape on the way in. validate()'s
206			// byte-level guards mean QueryEscape only ever sees safe input.
207			httpReq.SetBasicAuth(url.QueryEscape(req.ClientID), "")
208		}
