		ClientID:      testClientID,
		AuthorizePath: testAuthorizePath,
		TokenPath:     testTokenPath,
	}
	if _, err := c.Start(context.Background()); !errors.Is(err, ErrInsecureBaseURL) {
		t.Fatalf("Start() error = %v, want ErrInsecureBaseURL", err)
	}
}

