	// No newline: persistLogin's "Login complete." lands on this line,
	// reading "Waiting for sign-in... Login complete." like the device flow.
	fmt.Fprint(outW, "Waiting for sign-in... ")

	code, err := flow.Wait(ctx)
	if err != nil {
		return fmt.Errorf("complete login: %w", err)
	}

